const params=new URLSearchParams(location.hash.slice(1));let token=params.get('invitacion')||'';history.replaceState(null,'',location.pathname+location.search);const form=document.querySelector('[data-activate]'),status=document.querySelector('[data-result]');if(!token){form.hidden=true;status.textContent='Abre el enlace privado que te ha entregado Raúl. Si ha caducado, pídele una invitación nueva.';}
form.addEventListener('submit',async event=>{event.preventDefault();if(form.elements.password.value!==form.elements.confirmation.value){status.textContent='Las contraseñas no coinciden.';return;}const button=form.querySelector('button');button.disabled=true;try{const response=await fetch('/api/admin/delegates/activate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,password:form.elements.password.value})});const data=await response.json();if(!response.ok)throw Error(data.error||'No se pudo activar el acceso.');form.reset();form.hidden=true;token='';status.textContent='Acceso activado para '+data.alias+'. Entra con '+data.email+' y tu contraseña propia.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
